messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Low Poly 3D Humanoid Animation - Three.js</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #1a1a1a; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
    import * as THREE from './three.module.js';

    // --- Configuration ---
    const FPS = 60;
    const FRAME_TIME = 1000 / FPS;
    const CYCLE_DURATION = 10; // Seconds
    const STAND_1 = 2;
    const WALK = 3;
    const RUN = 3;
    const STAND_2 = 2;

    // --- Scene Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // Sky blue
    scene.fog = new THREE.Fog(0x87CEEB, 10, 50);

    const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(0, 3, 6);
    camera.lookAt(0, 1, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
    dirLight.position.set(5, 10, 7);
    dirLight.castShadow = true;
    dirLight.shadow.camera.left = -5;
    dirLight.shadow.camera.right = 5;
    dirLight.shadow.camera.top = 5;
    dirLight.shadow.camera.bottom = -5;
    scene.add(dirLight);

    // --- Environment (Treadmill) ---
    const groundGeo = new THREE.PlaneGeometry(20, 20);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.8 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Grid helper for movement visualization
    const gridHelper = new THREE.GridHelper(20, 20, 0x555555, 0x444444);
    scene.add(gridHelper);

    // --- Procedural Low Poly Humanoid ---
    const humanGroup = new THREE.Group();
    scene.add(humanGroup);

    // Materials
    const skinMat = new THREE.MeshStandardMaterial({ color: 0xffccaa, flatShading: true });
    const shirtMat = new THREE.MeshStandardMaterial({ color: 0x2233ff, flatShading: true });
    const pantsMat = new THREE.MeshStandardMaterial({ color: 0x333333, flatShading: true });

    // Body Parts
    const torsoGeo = new THREE.BoxGeometry(0.6, 1.2, 0.4);
    const torso = new THREE.Mesh(torsoGeo, shirtMat);
    torso.position.y = 1.5;
    torso.castShadow = true;
    humanGroup.add(torso);

    const neckGeo = new THREE.BoxGeometry(0.4, 0.3, 0.4);
    const neck = new THREE.Mesh(neckGeo, shirtMat);
    neck.position.y = 0.3;
    torso.add(neck);

    const headGeo = new THREE.BoxGeometry(0.4, 0.4, 0.4);
    const head = new THREE.Mesh(headGeo, skinMat);
    head.position.y = 0.6;
    neck.add(head);

    // Torso Pivot (for leaning)
    const torsoPivot = new THREE.Group();
    torsoPivot.position.y = 1.3; // Approximate center of mass
    torsoPivot.add(torso);
    torsoPivot.add(neck);
    torsoPivot.add(head);
    humanGroup.add(torsoPivot);

    // Arms
    const armGeo = new THREE.BoxGeometry(0.25, 1.0, 0.25);
    const leftArm = new THREE.Mesh(armGeo, shirtMat);
    leftArm.position.set(-0.5, 0.2, 0);
    leftArm.castShadow = true;
    torso.add(leftArm);

    const rightArm = new THREE.Mesh(armGeo, shirtMat);
    rightArm.position.set(0.5, 0.2, 0);
    rightArm.castShadow = true;
    torso.add(rightArm);

    // Legs
    const legGeo = new THREE.BoxGeometry(0.25, 1.0, 0.25);
    const leftLeg = new THREE.Mesh(legGeo, pantsMat);
    leftLeg.position.set(-0.25, -0.5, 0);
    leftLeg.castShadow = true;
    torso.add(leftLeg);

    const rightLeg = new THREE.Mesh(legGeo, pantsMat);
    rightLeg.position.set(0.25, -0.5, 0);
    rightLeg.castShadow = true;
    torso.add(rightLeg);

    // --- Animation State ---
    let time = 0;
    let phase = 'stand1'; // stand1, walk, run, stand2
    let cycleStartTime = 0;
    let isRunning = false;

    // Limb Targets (0 to 1, where 1 is max swing)
    let targetLegAngle = 0;
    let targetArmAngle = 0;
    let targetLean = 0;

    // --- Animation Loop ---
    const clock = new THREE.Clock();

    function updateState(dt) {
        // Determine current phase based on total elapsed time
        const currentTime = clock.getElapsedTime();
        const timeInCycle = currentTime % CYCLE_DURATION;

        if (timeInCycle < STAND_1) {
            phase = 'stand1';
            targetLean = 0;
            targetLegAngle = 0;
            targetArmAngle = 0;
        } else if (timeInCycle < STAND_1 + WALK) {
            phase = 'walk';
            targetLean = 0;
            targetLegAngle = 0.5; // Moderate swing
            targetArmAngle = 0.5;
        } else if (timeInCycle < STAND_1 + WALK + RUN) {
            phase = 'run';
            targetLean = -0.2; // Lean forward
            targetLegAngle = 0.9; // Large swing
            targetArmAngle = 0.9;
        } else {
            phase = 'stand2';
            targetLean = 0;
            targetLegAngle = 0;
            targetArmAngle = 0;
        }

        // Interpolate current values to targets
        // Using a simple lerp for smooth transitions between phases
        // We smooth the transition of the target itself by using sin waves based on time within phase
        // But for simplicity in this structure, we will interpolate the target value towards the desired state
        // based on a factor that changes over the phase duration.

        // Calculate progress within current phase
        let phaseProgress = 0;
        if (phase === 'stand1') {
            phaseProgress = timeInCycle / STAND_1;
        } else if (phase === 'walk') {
            phaseProgress = (timeInCycle - (STAND_1)) / WALK;
        } else if (phase === 'run') {
            phaseProgress = (timeInCycle - (STAND_1 + WALK)) / RUN;
        } else {
            phaseProgress = (timeInCycle - (STAND_1 + WALK + RUN)) / STAND_2;
        }

        // Clamp
        phaseProgress = Math.min(1, Math.max(0, phaseProgress));

        // Smoothly interpolate the target angles
        // For standing, we want to return to 0. For walking/running, we want to swing.

        if (phase === 'stand1' || phase === 'stand2') {
            targetLean = 0;
            targetLegAngle = 0;
            targetArmAngle = 0;
        } else {
            // For walking and running, use sine wave for rhythmic movement
            // Adjust frequency based on phase (run is faster frequency effectively due to larger amplitude)
            const freq = phase === 'run' ? 1.0 : 0.5; 
            const amp = phase === 'run' ? 1.0 : 0.5;

            // Add a slight offset to legs so they don't move perfectly in sync (unless it's a stiff animation, but staggered looks better)
            const legOffset = 0.2;
            const armOffset = 0.2;

            targetLean = phase === 'run' ? -0.15 : 0;
            targetLegAngle = Math.sin((currentTime * freq) + legOffset) * amp;
            targetArmAngle = Math.sin((currentTime * freq) + armOffset) * amp;
        }
    }

    function animate() {
        requestAnimationFrame(animate);

        const dt = clock.getDelta();

        // Update State
        updateState(dt);

        // Apply Interpolation
        // Use a linear interpolation factor
        const lerpFactor = 10 * dt; // Speed of limb movement

        // Torso Lean
        torsoPivot.rotation.z = THREE.MathUtils.lerp(torsoPivot.rotation.z, targetLean, lerpFactor);

        // Legs
        leftLeg.rotation.x = THREE.MathUtils.lerp(leftLeg.rotation.x, targetLegAngle, lerpFactor);
        rightLeg.rotation.x = THREE.MathUtils.lerp(rightLeg.rotation.x, -targetLegAngle, lerpFactor); // Opposite swing

        // Arms
        leftArm.rotation.x = THREE.MathUtils.lerp(leftArm.rotation.x, targetArmAngle, lerpFactor);
        rightArm.rotation.x = THREE.MathUtils.lerp(rightArm.rotation.x, -targetArmAngle, lerpFactor); // Opposite swing

        renderer.render(scene, camera);
    }

    animate();

    // Handle Resize
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

</script>
</body>
</html>
```
